 const stone=this.mat('pavement',[.55,.53,.46]),road=this.mat('asphalt',[.16,.18,.19]),grass=this.mat('park green',[.24,.35,.23]),white=this.mat('road paint',[.86,.83,.66]),wood=this.materials.wood;
 this.shape('District ground','box',[31,-.4,1.5],[106,.5,93],this.materials.dust);this.shape('Cemetery north verge','box',[31,-.4,-57.5],[106,.5,13],grass);this.shape('Western green belt','box',[7.5,-.4,-48],[59,.5,6],grass);this.shape('Eastern green belt','box',[78.5,-.4,-48],[11,.5,6],grass);
 this.shape('Main road','box',[31,-.08,25],[106,.12,10],road);for(let x=-20;x<84;x+=5)this.shape('Road divider','box',[x,.005,25],[2.4,.025,.15],white);
