 for(let i=0;i<4;i++){let x=32+i*13,z=i%2?-4:6;const color=this.mat('company '+i,[[.62,.56,.46],[.32,.42,.43],[.55,.39,.28],[.45,.47,.50]][i]);this.shape('Company building','box',[x,4,z],[9,8,10],color);this.obstacles.push({x,z,w:4.7,d:5.2});for(let floor=0;floor<3;floor++)for(let col=0;col<3;col++)this.shape('Office window','box',[x-2.8+col*2.8,2+floor*2.1,z+5.03],[1.7,1.35,.06],this.materials.window);this.sign(['PALMLINE LOGISTICS','ADE & CO. PRINTING','COASTLINE WORKS','UNITY ACCOUNTS'][i],x,1.3,z+5.1,8,'#284e53');}
