 for(let i=0;i<5;i++){let x=29+i*10;this.shape('Roadside shop','box',[x,1.6,40],[7,3.2,5],this.mat('shopfront '+i,[[.56,.32,.23],[.15,.36,.35],[.65,.55,.29],[.42,.39,.52],[.6,.47,.34]][i]));this.obstacles.push({x,z:40,w:3.7,d:2.7});this.sign(['BARBER','PHONE REPAIRS','BAKERY','PHARMACY','CAFÉ'][i],x,2.8,37.45,5,'#284e53');}
