 for(let i=0;i<12;i++){const x=20+(i%6)*10,z=-30-Math.floor(i/6)*6;this.shape('Tree trunk','cylinder',[x,1.2,z],[.35,2.4,.35],wood);this.shape('Tree canopy','sphere',[x,3,z],[3,3.5,3],grass);this.obstacles.push({x,z,w:.4,d:.4});}
 for(let i=0;i<10;i++){let dir=i<5?1:-1,lane=dir===1?22.3:27.7,x=-18+(i%5)*19;let car=this.pivot('Traffic vehicle '+i,[x,0,lane]);let paint=this.mat('car '+i,[[.78,.55,.12],[.2,.34,.43],[.58,.18,.13],[.70,.68,.58],[.20,.26,.24]][i%5]);this.shape('Car body','box',[0,.65,0],[3.8,.85,1.7],paint,car);this.shape('Car cabin','box',[0,1.25,0],[2,.7,1.5],this.materials.window,car);for(let side of [-1,1])for(let axle of [-1.2,1.2]){let wheel=this.shape('Wheel','cylinder',[axle,.35,side*.85],[.6,.18,.6],this.materials.rubber,car);wheel.setEulerAngles(90,0,0);}this.cars.push({entity:car,dir,lane,speed:0,desired:5+(i%3),stopped:false});}
