MidnightGrounds.prototype.newNpc=function(name,x,z,index,role){const n={entity:this.person(name,x,z,index),name,role:role||'shopper',state:'alive',hp:2,target:new pc.Vec3(x,0,z),home:new pc.Vec3(x,0,z),timer:0,phase:index,panic:0,fall:0,chat:0,chatCooldown:2+index,path:[],pathTime:0};this.npcs.push(n);return n;};
