 this.gripArms=[];for(let i=0;i<2;i++){this.player.rig.arms[i].enabled=false;this.gripArms.push({upper:this.shape('Courier upper arm','capsule',[0,0,0],[.16,.4,.16],this.materials.shirt0),lower:this.shape('Courier forearm','capsule',[0,0,0],[.13,.36,.13],this.materials.skin0),hand:this.shape('Courier hand','box',[0,0,0],[.14,.15,.10],this.materials.skin0)});}
