 rig.head=this.pivot('Head',[0,.83,0],rig.torso);this.shape('Face','sphere',[0,0,0],[.37,.46,.35],skin,rig.head);this.shape('Nose','sphere',[0,-.025,.18],[.095,.11,.10],skin,rig.head);
 for(var side=-1;side<=1;side+=2){this.shape('Ear','sphere',[side*.19,-.01,0],[.075,.12,.07],skin,rig.head);this.shape('Eye white','sphere',[side*.075,.035,.155],[.065,.036,.022],ivory,rig.head);this.shape('Pupil','sphere',[side*.075,.035,.169],[.028,.03,.015],hair,rig.head);this.shape('Eyebrow','box',[side*.075,.08,.16],[.09,.025,.02],hair,rig.head);}
 this.shape('Mouth','box',[0,-.105,.15],[.10,.022,.02],hair,rig.head);this.shape('Hair cap','sphere',[0,.16,-.025],[.39,.22,.36],hair,rig.head);
 if(index%3===1){this.shape('Headwrap','sphere',[0,.22,-.015],[.48,.32,.40],shirt,rig.head);this.shape('Headwrap knot','sphere',[.16,.34,-.03],[.23,.22,.23],shirt,rig.head);}
 if(index%3===2){this.shape('Cap crown','cylinder',[0,.23,0],[.40,.22,.38],shirt,rig.head);this.shape('Cap brim','box',[0,.16,.20],[.42,.04,.23],shirt,rig.head);}
 rig.arms=[];rig.elbows=[];rig.legs=[];rig.knees=[];
 for(var s=-1;s<=1;s+=2){var arm=this.pivot('Shoulder '+s,[s*.36,.44,0],rig.torso);this.shape('Shirt sleeve','box',[0,-.14,0],[.20,.32,.23],shirt,arm);this.shape('Upper arm','capsule',[0,-.26,0],[.14,.30,.15],skin,arm);var elbow=this.pivot('Elbow',[0,-.38,0],arm);this.shape('Forearm','capsule',[0,-.15,0],[.13,.34,.14],skin,elbow);this.shape('Hand','box',[0,-.34,.015],[.14,.16,.09],skin,elbow);rig.arms.push(arm);rig.elbows.push(elbow);
 var leg=this.pivot('Hip '+s,[s*.17,-.03,0],rig.hips);this.shape('Trouser thigh','box',[0,-.22,0],[.23,.46,.29],pants,leg);var knee=this.pivot('Knee',[0,-.45,0],leg);this.shape('Trouser calf','box',[0,-.19,0],[.19,.40,.23],pants,knee);this.shape('Shoe','box',[0,-.41,.08],[.23,.14,.39],sole,knee);rig.legs.push(leg);rig.knees.push(knee);}
