MidnightGrounds.prototype.pose=function(rig,walk,phase,drag){var swing=Math.sin(phase)*walk;rig.hips.setLocalPosition(0,.96+Math.abs(Math.sin(phase))*walk*.035,0);rig.torso.setLocalEulerAngles(drag?15:0,0,0);for(var i=0;i<2;i++){var v=swing*(i?1:-1);rig.legs[i].setLocalEulerAngles(v*33,0,0);rig.knees[i].setLocalEulerAngles(Math.max(0,-v)*40,0,0);rig.arms[i].setLocalEulerAngles(drag?-38:-v*26,0,i?-4:4);rig.elbows[i].setLocalEulerAngles(drag?-32:-12,0,0);}};
