MidnightGrounds.prototype.setupInput=function(){this.down=e=>{if(/^(INPUT|TEXTAREA)$/.test(e.target.tagName))return;let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!this.$('note').hidden&&k==='tab'){const bs=[...this.$('choices').querySelectorAll('button')];if(bs.length){e.preventDefault();let i=bs.indexOf(document.activeElement);bs[(i+(e.shiftKey?-1:1)+bs.length)%bs.length].focus();}return;}if(k==='escape'&&!e.repeat){if(this.started){if(!this.$('note').hidden)this.closeNote();else this.togglePause();}return;}if(!this.started||this.paused)return;this.keys[k]=true;if(e.repeat)return;if(k===' ')this.attack();if(k==='e')this.grab();if(k==='t')this.interact();if(k==='c')this.climb();if(k==='m')this.toggleMap();};this.up=e=>{this.keys[e.key.toLowerCase()]=false;};this.blur=()=>{this.keys={};if(this.started&&!this.paused)this.togglePause();};this.visibility=()=>{if(document.hidden)this.blur();};this.wheel=e=>{if(e.target===this.app.graphicsDevice.canvas){e.preventDefault();this.zoom=pc.math.clamp(this.zoom+Math.sign(e.deltaY),6,17);}};window.addEventListener('keydown',this.down);window.addEventListener('keyup',this.up);window.addEventListener('blur',this.blur);window.addEventListener('wheel',this.wheel,{passive:false});document.addEventListener('visibilitychange',this.visibility);};
