MidnightGrounds.prototype.refreshObjective=function(){const objectives=[['01 / THE LAST MESSAGE','Talk to Mama T in the market.','Market',-4,3],['02 / THE DISPATCH RECORD','Reach Palmline Logistics and inspect the dispatch terminal.','Business quarter',32,12.6],['03 / THE CEMETERY PARCEL','Visit Remembrance Gardens. Dig plot 1 from its edge.','Cemetery',43.5,-48],['04 / BEFORE THE NIGHT BUS','Meet Nia at Bus Stop 04, across the main road.','Bus stop',8,35],['CHAPTER COMPLETE','You found the last delivery. Explore freely or restart.','Bus stop',8,35]];this.objective=objectives[this.chapter];this.$('chapter').textContent=this.objective[0];this.$('objective').textContent=this.objective[1];};
