 if(p.distance(this.officePoint)<3){if(this.chapter===1){this.showNote('Dispatch record #041','Recipient: Nia. Delivery location: Remembrance Gardens, plot 1. A handwritten note reads: “The address was a hiding place. The caretaker knows. Bring the shovel.”',[{text:'Mark the cemetery on the map',run:()=>{this.chapter=2;this.refreshObjective();if(this.graves[0].letter)this.recoverParcel();else this.closeNote();}}]);}else this.showNote('Palmline dispatch desk','A delivery log and a folded cemetery plan sit on the desk. Follow the current lead in your journal.');return;}
 if(this.chapter===3&&p.distance(this.busStop)<4){this.chapter=4;this.storyComplete=true;this.refreshObjective();this.showNote('The last delivery',this.nia.state==='alive'?'Nia steps out of the shelter. “The cemetery address was where I hid your letters. I wanted to bring them back before our last bus.” She hands you the parcel: every small note you ever wrote her. Tonight, you found your way back to each other.':'The parcel is waiting on the bus-stop bench, beside Nia’s final note. The district falls quiet. Your choices have changed the ending.',[{text:'Keep exploring',run:()=>this.closeNote()},{text:'Start a new story',run:()=>location.reload()}]);return;}
